package com.example.editor.grammar.persistence;
import java.util.*;
import org.springframework.stereotype.Repository;
import com.example.editor.grammar.GrammarProperties;
import com.example.editor.grammar.core.GrammarDefinitionModel;
import com.example.editor.persistence.*;
import com.example.editor.validation.persistence.StoredCanonicalDocument;
import tools.jackson.databind.ObjectMapper;
@Repository
public class JsonGrammarRepository implements GrammarRepository {
    private final GrammarProperties properties; private final CanonicalDocumentStore<GrammarDefinitionModel> store;
    /** Descripción: Inicializa una instancia de JsonGrammarRepository con sus dependencias y datos de entrada. Entradas: properties: configuración que gobierna el comportamiento; mapper: componente de conversión utilizado durante el procesamiento; stores: dato de entrada necesario para la operación. Salida: deja la instancia inicializada y lista para su uso. */ public JsonGrammarRepository(GrammarProperties properties, ObjectMapper mapper, CanonicalDocumentStoreFactory stores){this.properties=properties;this.store=stores.create(new CanonicalDocumentStoreSpec<>("grammar.definition",properties.getDirectory(),properties.getFileSuffix(),properties.isUseEtag(),mapper,GrammarDefinitionModel.class,GrammarDefinitionModel::id));}
    /** Descripción: Crea o prepara el resultado de «create» dentro de JsonGrammarRepository. Entradas: m: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ public StoredCanonicalDocument<GrammarDefinitionModel> create(GrammarDefinitionModel m){requireEnabled();return store.create(m);} /** Descripción: Actualiza el estado gestionado por JsonGrammarRepository mediante la operación «replace». Entradas: id: identificador que delimita el recurso objetivo; m: dato de entrada necesario para la operación; e: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ public StoredCanonicalDocument<GrammarDefinitionModel> replace(String id,GrammarDefinitionModel m,String e){requireEnabled();return store.replace(id,m,e);} /** Descripción: Obtiene la información correspondiente a «findById» dentro de JsonGrammarRepository. Entradas: id: identificador que delimita el recurso objetivo. Salida: devuelve el resultado definido por el contrato del método. */ public Optional<StoredCanonicalDocument<GrammarDefinitionModel>> findById(String id){requireEnabled();return store.find(id);} /** Descripción: Obtiene la información correspondiente a «listIds» dentro de JsonGrammarRepository. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public List<String> listIds(){requireEnabled();return store.listIds();} /** Descripción: Elimina o libera el recurso gestionado por «delete» de forma controlada. Entradas: id: identificador que delimita el recurso objetivo; e: dato de entrada necesario para la operación. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void delete(String id,String e){requireEnabled();store.delete(id,e);} /** Descripción: Valida las condiciones necesarias para «requireEnabled» y rechaza entradas no válidas. Entradas: no requiere parámetros de entrada. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ private void requireEnabled(){if(!properties.isEnabled())throw new IllegalStateException("Grammar persistence is disabled");}
}
